import{r as e}from"./auth-bgkSYldb.js";var t={list(t=0,n=20){return e.get(`/workspaces/current/smtp-servers`,{params:{page:t,size:n}})},get(t){return e.get(`/workspaces/current/smtp-servers/${t}`)},create(t){return e.post(`/workspaces/current/smtp-servers`,t)},update(t,n){return e.put(`/workspaces/current/smtp-servers/${t}`,n)},delete(t){return e.delete(`/workspaces/current/smtp-servers/${t}`)},test(t){return e.post(`/workspaces/current/smtp-servers/${t}/test`)}};export{t};